question.answer:
package main

type Step func(int) int

// double is fixed. It is one station on the line.
func double(n int) int {
	return n * 2
}

func applyAll(x int, steps ...Step) int {
	for _, step := range steps {
		if step == nil {
			continue
		}
		x = step(x)
	}
	return x
}

testcode.text:
line := []Step{double, nil, func(n int) int { return n - 1 }, double}
fmt.Println(applyAll(1, line...))
fmt.Println(applyAll(0, line[1:]...))

