question.answer:
package main

import "sort"

// Player is one entry on the club's board.
type Player struct {
	Name  string
	Score int
}

func rank(players []Player) {
	sort.Slice(players, func(i, j int) bool {
		if players[i].Score != players[j].Score {
			return players[i].Score > players[j].Score
		}
		return players[i].Name < players[j].Name
	})
}

testcode.text:
board := []Player{{Name: "Bo", Score: 12}, {Name: "Ada", Score: 20}, {Name: "Cy", Score: 15}}
rank(board)
for _, p := range board {
	fmt.Println(p.Name, p.Score)
}

board := []Player{{Name: "Di", Score: 20}, {Name: "Cy", Score: 20}, {Name: "Bo", Score: 20}, {Name: "Ada", Score: 25}}
rank(board)
for _, p := range board {
	fmt.Println(p.Name, p.Score)
}

board := []Player{{"Ada", 10}, {"Bo", 20}, {"Cy", 30}, {"Di", 10}, {"Ed", 20}, {"Fay", 30}, {"Gus", 10}, {"Hal", 20}, {"Ivy", 30}, {"Jo", 10}, {"Kim", 20}, {"Lee", 30}, {"Max", 10}}
rank(board)
