	fmt.Println(p.Name, p.Score)
}

board := []Player{{"Max", 30}, {"Lee", 20}, {"Kim", 30}, {"Jo", 20}, {"Ivy", 30}, {"Hal", 20}, {"Gus", 30}, {"Fay", 20}, {"Ed", 30}, {"Di", 20}, {"Cy", 30}, {"Bo", 20}, {"Ada", 30}}
rank(board)
for _, p := range board {
	fmt.Println(p.Name, p.Score)
}
var empty []Player
rank(empty)
fmt.Println(len(empty))

