question.answer:
package main

func newMachine() func() int {
	count := 0
	return func() int {
		count++
		return count
	}
}

func newGate(capacity int) func() bool {
	admitted := 0
	return func() bool {
		if admitted >= capacity {
			return false
		}
		admitted++
		return true
	}
}

testcode.text:
admit, next := newGate(3), newMachine()
for i := 0; i < 5; i++ {
	if admit() {
		fmt.Println("ticket", next())
	} else {
		fmt.Println("locked")
	}
}
shut := newGate(0)
fmt.Println(shut(), newGate(1)())
